const body = $json.body ?? {};
const job = body.job ?? body;
const clean = (value, max = 2500) => String(value ?? '').trim().slice(0, max);
const list = (value, max = 30) => Array.isArray(value) ? value.map((item) => clean(item, 500)).filter(Boolean).slice(0, max) : [];
const jobId = clean(body.jobId || job.id || job.jobId, 160);
if (!/^RES[0-9A-Za-z_-]+$/.test(jobId)) throw new Error('Invalid or missing Merqiva research jobId');
const rawCallback = clean(body.callbackUrl || job.callbackUrl, 1000);
let callback;
try { callback = new URL(rawCallback); } catch { throw new Error('Invalid callback URL'); }
const allowedHosts = new Set(['merqivaintel.com','www.merqivaintel.com']);
if (callback.protocol !== 'https:' || !allowedHosts.has(callback.hostname) || callback.pathname !== '/api/research/callback') throw new Error('Callback URL is not an approved Merqiva endpoint');
const productName = clean(job.productName, 240);
const researchQuestion = clean(job.researchQuestion, 2500);
if (!productName || !researchQuestion) throw new Error('productName and researchQuestion are required');
return [{json:{jobId,callbackUrl:callback.toString(),productName,productId:clean(job.productId,160),targetMarket:clean(job.targetMarket,500),researchQuestion,targetCompanyTypes:list(job.targetCompanyTypes),targetVesselTypes:list(job.targetVesselTypes),relevantSignals:list(job.relevantSignals),targetDecisionMakerRoles:list(job.targetDecisionMakerRoles),maxOpportunities:Math.max(1,Math.min(10,Number(job.maxOpportunities)||10)),language:['en','ar'].includes(job.language)?job.language:'en'}}];
